function applyTheme() {
  const root = document.documentElement;
  if (S.theme === 'light' || S.theme === 'dark') { root.setAttribute('data-theme', S.theme); _themeSetByApp = true; }
  else if (_themeSetByApp) { root.removeAttribute('data-theme'); _themeSetByApp = false; }
}

/* ---- Aspecto (Fase 3): estilo nuevo/clásico, paleta y tipografía de las cifras. Se guarda en este dispositivo. ---- */
const PALETAS = [['violeta', 'Violeta', '#6D3FE0', '#A98BFF'], ['cobalto', 'Cobalto', '#1F63E0', '#6FA2FF'], ['turquesa', 'Turquesa', '#07797C', '#34D1C8'], ['frambuesa', 'Frambuesa', '#CC2065', '#FF6B9F'], ['esmeralda', 'Esmeralda', '#0A7A42', '#3EE08C']];
const TIPOS_CIFRA = [
  ['bricolage', 'Con carácter', "'Bricolage Grotesque', sans-serif", 'Bricolage+Grotesque:opsz,wght@12..96,500..800'],
  ['fraunces', 'Clásica', "'Fraunces', serif", null],
  ['space', 'Técnica', "'Space Grotesk', sans-serif", 'Space+Grotesk:wght@500..700'],
  ['outfit', 'Geométrica', "'Outfit', sans-serif", 'Outfit:wght@500..700'],
  ['nunito', 'Redondeada', "'Nunito', sans-serif", 'Nunito:wght@600..900'],
];
function cargarFuente(id) {
  const t = TIPOS_CIFRA.find((x) => x[0] === id);
  if (!t || !t[3] || id === 'bricolage' || document.querySelector('link[data-fuente="' + id + '"]')) return;
  const l = document.createElement('link'); l.rel = 'stylesheet'; l.setAttribute('data-fuente', id); l.href = 'https://fonts.googleapis.com/css2?family=' + t[3] + '&display=swap'; document.head.appendChild(l);
}
const FONDOS = [['neutro', 'Neutro'], ['tinte', 'Con tu color'], ['puro', 'Negro puro', 'Blanco']];
function applyLook(suave) {
  const r = document.documentElement;
  if (!PALETAS.some((x) => x[0] === S.paleta)) S.paleta = 'violeta';
  if (!TIPOS_CIFRA.some((x) => x[0] === S.tipo)) S.tipo = 'bricolage';
  if (suave && !reduceMotion()) { r.classList.add('cambiando'); clearTimeout(applyLook._t); applyLook._t = setTimeout(() => r.classList.remove('cambiando'), 600); }
  if (FONDOS.every((x) => x[0] !== S.fondo)) S.fondo = 'neutro';
  r.setAttribute('data-look', S.look); r.setAttribute('data-paleta', S.paleta); r.setAttribute('data-tipo', S.tipo); r.setAttribute('data-fondo', S.fondo);
  if (S.look === 'nuevo') cargarFuente(S.tipo);
  try { document.querySelectorAll('meta[name="theme-color"]').forEach((m) => { const osc = /dark/.test(m.getAttribute('media') || ''); m.setAttribute('content', S.look === 'nuevo' ? (S.fondo === 'puro' ? (osc ? '#000000' : '#FFFFFF') : (osc ? '#0A0A0C' : '#F5F5F2')) : (osc ? '#14172A' : '#F1EFE8')); }); } catch (e) { /* sin meta */ }
}
function aspectoHtml() {
  const nuevo = S.look === 'nuevo', v = vibraOn(), so = sonidoOn(), sw = (k, on) => '<button type="button" class="switch' + (on ? ' on' : '') + '" role="switch" aria-checked="' + on + '" aria-label="' + (k === 'vibra' ? 'Vibración' : 'Sonido') + '" ' + act('setSens', k) + '></button>';
  const pal = PALETAS.map(([id, n, l, d]) => '<button type="button" class="asp-sw' + (S.paleta === id ? ' on' : '') + '" ' + act('setPaleta', id) + '><i style="background:linear-gradient(135deg,' + l + ' 50%,' + d + ' 50%)">' + ic('check') + '</i>' + n + '</button>').join('');
  const tip = TIPOS_CIFRA.map(([id, n, f]) => '<button type="button" class="asp-tp' + (S.tipo === id ? ' on' : '') + '" ' + act('setTipo', id) + '><span class="n" style="--asp-f:' + f + '">' + money(1234.56) + '</span><span class="l">' + n + '</span></button>').join('');
  return '<div class="handle"></div><h2>Aspecto y sensaciones</h2>' +
    '<div class="asp-sec"><div class="section-title" style="margin-top:0;">Color</div><div class="asp-pal">' + pal + '</div></div>' +
    '<div class="asp-sec"><div class="section-title">Tema</div><div class="segmented asp-tema">' + [['auto', 'Auto'], ['light', 'Claro'], ['dark', 'Oscuro']].map(([k, l]) => '<button type="button" class="' + ((S.theme || 'auto') === k ? 'active' : '') + '" ' + act('setTheme', k) + '>' + l + '</button>').join('') + '</div></div>' +
    '<div class="asp-sec"><div class="section-title">Fondo</div><div class="asp-fondos">' + FONDOS.map(([k, l, lClaro]) => '<button type="button" class="asp-fondo f-' + k + (S.fondo === k ? ' on' : '') + '" aria-pressed="' + (S.fondo === k) + '" ' + act('setFondo', k) + '><span class="asp-fondo-v"><i></i><i></i></span><span class="asp-fondo-l">' + (lClaro ? '<span class="osc">' + l + '</span><span class="cla">' + lClaro + '</span>' : l) + '</span></button>').join('') + '</div></div>' +
    '<div class="asp-sec asp-solo-nuevo"><div class="section-title">Cifras y titulares</div><div class="asp-tipos">' + tip + '</div></div>' +
    '<div class="asp-sec"><div class="section-title">Sensaciones</div>' +
    '<div class="asp-fila"><div class="t">Vibración<span>Un toque suave al guardar, completar o conseguir una meta.</span></div><button type="button" class="link" ' + act('probarSens', 'ok') + '>Probar</button>' + sw('vibra', v) + '</div>' +
    '<div class="asp-fila"><div class="t">Sonido<span>Sonidos cortos y suaves. Se pueden apagar aquí en cualquier momento.</span></div><button type="button" class="link" ' + act('probarSens', 'hito') + '>Probar</button>' + sw('sonido', so) + '</div>' +
    (typeof navigator !== 'undefined' && !navigator.vibrate ? '<div class="asp-nota">Este dispositivo no deja que las páginas web vibren (pasa en iPhone). Probamos un truco de iOS 17.4 o más que puede funcionar o no. En Android, y en la app instalada, sí funciona.</div>' : '') + '</div>' +
    '<div class="actions"><button class="btn accent block" ' + act('closeSheet') + '>Listo</button></div>';
}
function refrescarAspecto() { if (FORM && FORM.kind === 'aspecto' && $('#sheetBackdrop')) { const sc = $('#sheetBackdrop .sheet'), y = sc ? sc.scrollTop : 0; updateSheet(aspectoHtml()); const sh = $('#sheetBackdrop .sheet'); if (sh) sh.scrollTop = y; } }

const DEFAULT_CONFIG = {
  categoriasGasto: [], facturas: [], ahorro: [], deudas: [], ingresos: [],
  metodosPago: ['Efectivo', 'Tarjeta débito', 'Tarjeta crédito', 'Transferencia', 'Bizum', 'Otro'],
  categoriasTareas: [],
};
function cfg() { return Object.assign({}, DEFAULT_CONFIG, S.config || {}); }

/* ============================================================
   CAPA DE DATOS (capacidad db de la plataforma)
   ============================================================ */
let _unsubs = [];

function errMsg(e) {
  const code = e && e.code;
  if (code === '23505') return 'Ya existe un registro con ese identificador.';
  if (code === '42501' || code === 'PGRST301' || code === 401 || code === 403) return 'No tienes permiso para guardar este cambio (revisa tu sesión).';
  if (code === 'network' || code === 'TypeError') return 'No se pudo conectar. Revisa tu conexión a internet.';
  return 'No se pudo guardar. Revisa tu conexión.';
}
async function withRetry(fn, tries) {
  tries = tries || 4;
  let last;
  for (let i = 0; i < tries; i++) {
    try { return await fn(); }
    catch (e) {
      last = e;
      const retryable = !e || !e.code || e.code === 'network' || (typeof e.code === 'number' && e.code >= 500);
      if (retryable && i < tries - 1) { await sleep(300 * (i + 1) + Math.random() * 200); continue; }
      throw e;
    }
  }
  throw last;
}
// Ejecuta una escritura con reintentos y avisa si falla. Devuelve true/false.
async function write(fn) {
  try { await withRetry(fn); return true; }
  catch (e) { console.error(e); toast(errMsg(e)); return false; }
}

// La sesión (login) determina si hay datos que cargar. Ver data-layer.js (window.Auth / window.Data).
function allLoaded() { const l = S.loaded; return l.mov && l.tar && l.golf && l.cfg; }

function subscribeAll() {
  _unsubs.forEach((u) => { try { u(); } catch (e) { /* noop */ } });
  _unsubs = [];
  const fail = (key, msg) => () => { S.loaded[key] = true; toast(msg); render(); };
  _unsubs.push(S.db.collection('movimientos').onSnapshot((snap) => {
    S._movsRaw = snap.docs.map((d) => Object.assign({ id: d.id }, d.data())); aplicarMovs(); S.loaded.mov = true; render();
  }, fail('mov', 'No se pudieron cargar los movimientos')));
  _unsubs.push(S.db.collection('tareas').onSnapshot((snap) => {
    S.tareas = snap.docs.map((d) => Object.assign({ id: d.id }, d.data())); S.loaded.tar = true; render();
  }, fail('tar', 'No se pudieron cargar las tareas')));
  _unsubs.push(S.db.collection('golf').onSnapshot((snap) => {
    S.golf = snap.docs.map((d) => Object.assign({ id: d.id }, d.data())); S.loaded.golf = true; render();
  }, fail('golf', 'No se pudo cargar Golf Reventa')));
  if (S.db.compartidos) _unsubs.push(S.db.compartidos.suscribir((rows) => {
    S.compartidos = rows;
    // si aparece algo de un grupo o persona que aún no conocemos, se recargan los grupos (una vez por grupo)
    const vistos = S._gruposVistos || (S._gruposVistos = {});
    const nuevos = rows.filter((c) => !grupoDe(c.grupoId) && !vistos[c.grupoId]);
    if (nuevos.length && !S._gruposCargando) {
      nuevos.forEach((c) => { vistos[c.grupoId] = 1; });
      S._gruposCargando = true;
      cargarGrupos().then(() => { S._gruposCargando = false; render(); refrescarSheetCompartido(); });
    }
    render(); refrescarSheetCompartido();
  }, (e) => { console.error(e); S.compartidos = S.compartidos || []; }));
  if (S.db.aportes) _unsubs.push(S.db.aportes.suscribir((rows) => { S.aportes = rows; render(); }, (e) => { console.error(e); S.aportes = S.aportes || []; }));
  if (S.db.agenda) _unsubs.push(S.db.agenda.suscribir((rows) => { S.agenda = rows; render(); refrescarSheetCompartido(); }, (e) => { console.error(e); S.agenda = S.agenda || []; }));
  if (S.db.carpetas) _unsubs.push(S.db.carpetas.suscribir((rows) => { S.carpetas = rows; render(); refrescarSheetCompartido(); }, (e) => { console.error(e); S.carpetas = S.carpetas || []; }));
  if (S.db.objetivos) _unsubs.push(S.db.objetivos.suscribir((rows) => { S.objetivos = rows; render(); refrescarSheetCompartido(); }, (e) => { console.error(e); S.objetivos = S.objetivos || []; }));
  _unsubs.push(S.db.doc('config/app').onSnapshot((snap) => {
    S.config = snap.exists ? snap.data() : null; S.loaded.cfg = true; if (S._movsRaw) aplicarMovs(); sincronizarMes(); maybeStartOnboarding(); render(); maybeUnirse(); maybeNovedades(); asegurarIdsMetas(); if (S.grupos == null && !S._gruposCargando) { S._gruposCargando = true; cargarGrupos().then(() => { S._gruposCargando = false; }); }
  }, fail('cfg', 'No se pudo cargar la configuración')));
}

/* -------- Config: escrituras en serie (una a la vez sobre el mismo documento) -------- */
let _cfgChain = Promise.resolve();
function saveConfig(partial) {
  S.config = Object.assign({}, cfg(), partial);
  const job = _cfgChain.then(async () => {
    await write(() => S.db.doc('config/app').update(partial));
  });
  _cfgChain = job;
  return job;
}

/* ============================================================
   CÁLCULOS
   ============================================================ */
function movsDelMes(anio, mes) {
  const k = anio + '-' + pad2(mes);
  return movsEfectivos().filter((m) => mesDe(m.fecha || '') === k);
}
function sumTipo(movs, tipo) { return movs.filter((m) => m.tipo === tipo).reduce((a, m) => a + num(m.importe), 0); }
function kpisMes(anio, mes) {
  const movs = movsDelMes(anio, mes);
  const ingresos = sumTipo(movs, 'Ingreso'), facturas = sumTipo(movs, 'Factura'), gastos = sumTipo(movs, 'Gasto');
  const ahorro = sumTipo(movs, 'Ahorro'), deuda = sumTipo(movs, 'Deuda'), inversion = sumTipo(movs, 'Inversión');
  return { ingresos, facturas, gastos, ahorro, inversion, deuda, disponible: ingresos - facturas - gastos - ahorro - inversion - deuda, movs };
}
function gastoPorCategoria(movs) {
  const map = {};
  movs.filter((m) => m.tipo === 'Gasto' || m.tipo === 'Factura').forEach((m) => { map[m.categoria] = (map[m.categoria] || 0) + num(m.importe); });
  return map;
}
function tareasVencidas() { return S.tareas.filter((t) => t.estado !== 'Completado' && t.fechaLimite && daysUntil(t.fechaLimite) < 0); }
function golfTotales() {
  let inv = 0, ben = 0, enCartera = 0;
  S.golf.forEach((g) => {
    inv += num(g.invertido);
    if (g.venta != null && g.venta !== '') ben += num(g.venta) - num(g.invertido); else enCartera++;
  });
  return { inv, ben, enCartera };
}
function prioridadPeso(p) { return { Alta: 3, Media: 2, Baja: 1 }[p] || 0; }
function cmpTarea(a, b) {
  const va = a.fechaLimite && daysUntil(a.fechaLimite) < 0 ? 1 : 0, vb = b.fechaLimite && daysUntil(b.fechaLimite) < 0 ? 1 : 0;
  return (vb - va) || (prioridadPeso(b.prioridad) - prioridadPeso(a.prioridad)) ||
    (a.fechaLimite || '9999').localeCompare(b.fechaLimite || '9999') || (a.nombre || '').localeCompare(b.nombre || '');
}
function cmpMov(a, b) { return (b.fecha || '').localeCompare(a.fecha || '') || (num(b.creadoEn || b.orden) - num(a.creadoEn || a.orden)); }
function presupuestoExcedido(anio, mes) {
  const map = gastoPorCategoria(movsDelMes(anio, mes));
  return catsGasto().filter((c) => c.nombre && c.presupuesto && (map[c.nombre] || 0) > c.presupuesto)
    .map((c) => ({ categoria: c.nombre, real: map[c.nombre], presupuesto: c.presupuesto }));
}
/* ============================================================
   CATEGORÍAS ESTÁNDAR (12/10/2026): iguales para todos y no se pueden borrar.
   Así un gasto compartido cae en la misma categoría para cada persona. Además cada uno puede
   crear las suyas (personalizadas) y apuntar un detalle (subcategoría: «Uñas», «Golf», «Spotify»).
   Las facturas son «gastos fijos»: tipo Factura, con categoría estándar y el recibo como detalle.
   ============================================================ */
const CATS_STD = [
  { n: 'Supermercado', ic: 'cart', d: 'Comida y cosas de casa' },
  { n: 'Restaurantes y bares', ic: 'fork', d: 'Comer fuera, cañas, cafés' },
  { n: 'Vivienda', ic: 'home', d: 'Alquiler o hipoteca, comunidad' },
  { n: 'Suministros', ic: 'bolt', d: 'Luz, agua, gas, internet, móvil' },
  { n: 'Transporte', ic: 'coche2', d: 'Gasolina, parking, coche, transporte público' },
  { n: 'Ocio', ic: 'film', d: 'Cine, conciertos, planes' },
  { n: 'Deporte', ic: 'ball', d: 'Gimnasio, golf, pádel' },
  { n: 'Compras', ic: 'shirt', d: 'Ropa y cosas' },
  { n: 'Salud y cuidado personal', ic: 'heart', d: 'Farmacia, médico, pelu, uñas' },
  { n: 'Regalos', ic: 'gift', d: 'Cumpleaños, detalles' },
  { n: 'Viajes', ic: 'plane', d: 'Hoteles, vuelos, escapadas' },
  { n: 'Suscripciones', ic: 'play', d: 'Spotify, Netflix, apps' },
  { n: 'Seguros', ic: 'shield', d: 'Coche, hogar, salud' },
  { n: 'Educación', ic: 'book', d: 'Cursos, libros, academia' },
  { n: 'Mascotas', ic: 'paw', d: 'Comida, veterinario' },
  { n: 'Otros', ic: 'tag', d: 'Lo que no encaja en ninguna' },
];
const CAT_STD_POR = {}; CATS_STD.forEach((c) => { CAT_STD_POR[normName(c.n)] = c; });
// Nombres que significan lo mismo que una estándar (para importar archivos y datos antiguos)
const ALIAS_STD = {
  groceries: 'Supermercado', 'alimentación': 'Supermercado', alimentacion: 'Supermercado', compra: 'Supermercado', 'compra semanal': 'Supermercado', supermercados: 'Supermercado',
  'dining out': 'Restaurantes y bares', restaurantes: 'Restaurantes y bares', restaurante: 'Restaurantes y bares', bares: 'Restaurantes y bares', 'comer fuera': 'Restaurantes y bares',
  shopping: 'Compras', ropa: 'Compras', gifts: 'Regalos', regalo: 'Regalos', entertainment: 'Ocio', salud: 'Salud y cuidado personal', health: 'Salud y cuidado personal',
  travel: 'Viajes', viaje: 'Viajes', other: 'Otros', otro: 'Otros', hogar: 'Vivienda', casa: 'Vivienda', housing: 'Vivienda', rent: 'Vivienda', alquiler: 'Vivienda',
  transport: 'Transporte', subscriptions: 'Suscripciones', suscripción: 'Suscripciones', education: 'Educación', educacion: 'Educación', pets: 'Mascotas', mascota: 'Mascotas',
  insurance: 'Seguros', seguro: 'Seguros', utilities: 'Suministros', facturas: 'Suministros', sport: 'Deporte', sports: 'Deporte', deportes: 'Deporte', gym: 'Deporte', gimnasio: 'Deporte',
};
// Para recibos y archivos: adivina la estándar por el nombre (Spotify → Suscripciones, Rent → Vivienda…)
const ADIVINA_STD = [
  [/spotify|netflix|hbo|disney|prime video|amazon prime|claude|chatgpt|openai|icloud|google one|youtube|apple|suscrip|dazn|filmin/, 'Suscripciones'],
  [/seguro|insurance|mapfre|mutua|axa|allianz|sanitas|adeslas|asisa|linea directa|l[ií]nea directa/, 'Seguros'],
  [/alquiler|rent|hipoteca|comunidad|ibi|piso|vivienda/, 'Vivienda'],
  [/luz|agua|gas|internet|wifi|fibra|m[oó]vil|phone|tel[eé]fono|iberdrola|endesa|naturgy|digi|movistar|vodafone|orange|o2|electric/, 'Suministros'],
  [/gym|gimnasio|golf|p[aá]del|fitness|deporte|club/, 'Deporte'],
  [/compras? (del )?mes|supermerc|mercadona|lidl|carrefour|aldi|alcampo|eroski|grocer|alimentaci/, 'Supermercado'],
  [/gasolin|petrol|repsol|cepsa|parking|aparcam|coche|taxi|uber|cabify|metro|renfe|tren|bus|peaje|itv/, 'Transporte'],
  [/restaur|birra|cerveza|bar|cafeter|dining|glovo|just ?eat|uber ?eats/, 'Restaurantes y bares'],
  [/cine|concierto|teatro|entertainment|ocio|fiesta|oktoberfest|palomitas/, 'Ocio'],
  [/farmac|m[eé]dic|dentista|pelu|u[ñn]as|est[eé]tica|autocuidado|colonia|perfum|salud/, 'Salud y cuidado personal'],
  [/regalo|gift/, 'Regalos'], [/viaje|hotel|vuelo|airbnb|booking|ryanair|vueling|iberia/, 'Viajes'],
  [/curso|academia|universidad|libro|educa/, 'Educación'], [/veterin|mascota|perro|gato/, 'Mascotas'],
  [/shopping|ropa|zara|primark|amazon|wallapop|vinted|ikea|compras/, 'Compras'],
];
function catStd(n) { return CAT_STD_POR[normName(n)] || null; }
function esCatStd(n) { return !!catStd(n); }
function adivinarCatStd(texto) { const t = normDesc(texto || ''); const r = ADIVINA_STD.find(([re]) => re.test(t)); return r ? r[1] : null; }
// Lista de categorías de gasto de esta persona: las estándar (con su presupuesto) y después las personalizadas
function catsGasto() {
  const propias = ((cfg().categoriasGasto) || []).filter((c) => c && c.nombre);
  const por = {}; propias.forEach((c) => { por[normName(c.nombre)] = c; });
  return CATS_STD.map((s) => Object.assign({ presupuesto: null }, por[normName(s.n)] || {}, { nombre: s.n, std: true }))
    .concat(propias.filter((c) => !esCatStd(c.nombre)).map((c) => Object.assign({}, c, { std: false })));
}
function esCatGasto(n) { const k = normName(n); return !!k && catsGasto().some((c) => normName(c.nombre) === k); }
// La categoría de un recibo: la que tenga puesta; si no, se adivina por el nombre; si no, Otros
function catDeRecibo(nombre) {
  const it = (cfg().facturas || []).find((x) => x && normName(x.nombre) === normName(nombre));
  if (it && it.categoria && esCatGasto(it.categoria)) return catStd(it.categoria) ? catStd(it.categoria).n : it.categoria;
  return adivinarCatStd(nombre) || 'Otros';
}
// Pone en orden la categoría de un gasto: nombres equivalentes → estándar; facturas antiguas (categoría = recibo) → categoría + recibo como detalle
function catNorm(tipo, categoria, sub) {
  if (tipo !== 'Gasto' && tipo !== 'Factura') return { categoria, subcategoria: sub || null };
  const c = (categoria || '').trim();
  if (catStd(c)) return { categoria: catStd(c).n, subcategoria: sub || null };
  if (tipo === 'Factura' && !sub && c && !esCatGasto(c)) return { categoria: catDeRecibo(c), subcategoria: c };
  if (ALIAS_STD[normName(c)] && !(cfg().categoriasGasto || []).some((x) => x && normName(x.nombre) === normName(c))) return { categoria: ALIAS_STD[normName(c)], subcategoria: sub || null }; // si la tienes como personalizada, se respeta
  return { categoria: c, subcategoria: sub || null };
}
function normMov(m) {
  if (m.tipo !== 'Gasto' && m.tipo !== 'Factura') return m;
  const r = catNorm(m.tipo, m.categoria, m.subcategoria);
  return r.categoria === m.categoria && (r.subcategoria || null) === (m.subcategoria || null) ? m : Object.assign({}, m, r);
}
// Los traspasos entre cuentas van aparte: no son gasto ni ingreso, así ninguna suma los ve
function esTraspaso(m) { return !!m && m.tipo === 'Traspaso'; }
function aplicarMovs() { const raw = S._movsRaw || []; S.traspasos = raw.filter(esTraspaso); S.movimientos = raw.filter((m) => !esTraspaso(m)).map(normMov); }
const tipoTxt = (t) => (t === 'Factura' ? 'Pago fijo' : t === 'Ahorro' ? 'Apartar' : t);
// Subcategorías que ya has usado en una categoría (y los recibos de esa categoría si es un gasto fijo)
function subcatsDe(cat, fijo) {
  const k = normName(cat), cuenta = {};
  if (!k) return [];
  if (fijo) (cfg().facturas || []).forEach((x) => { if (x && x.nombre && normName(catDeRecibo(x.nombre)) === k) cuenta[x.nombre] = (cuenta[x.nombre] || 0) + 100; });
  movsEfectivos().forEach((m) => { if ((m.tipo === 'Gasto' || m.tipo === 'Factura') && m.subcategoria && normName(m.categoria) === k && (!fijo || m.tipo === 'Factura')) cuenta[m.subcategoria] = (cuenta[m.subcategoria] || 0) + 1; });
  return Object.keys(cuenta).sort((a, b) => cuenta[b] - cuenta[a]).slice(0, 10);
}
function categoriasPorTipo(tipo) {
  const c = cfg();
  let arr = [];
  if (tipo === 'Gasto' || tipo === 'Factura') arr = catsGasto().map((x) => x.nombre);
  else if (tipo === 'Ahorro') arr = (c.ahorro || []).filter((x) => x && x.nombre && x.tipo !== 'inversion').map((x) => x.nombre);
  else if (tipo === 'Inversión') { const seen = {}; S.movimientos.forEach((m) => { if (m.tipo === 'Inversión' && m.categoria) seen[m.categoria] = (seen[m.categoria] || 0) + 1; }); arr = Object.keys(seen).sort((a, b) => seen[b] - seen[a]); }
  else if (tipo === 'Deuda') arr = (c.deudas || []).map((x) => x.nombre);
  else if (tipo === 'Ingreso') arr = (c.ingresos || []).slice();
  return arr.filter(Boolean);
}

