  const vacias = cats.filter((c) => !(num(c.presupuesto) > 0) && !(catMap[c.nombre] > 0.004)).map((c) => ({ n: c.nombre, l: c.nombre, v: 0, color: colorCat(c.nombre), pres: 0, nMov: 0, subs: null, sitios: null }));
