const COLORES_PERSONA = ['#B8752A', '#2F6F52', '#7A5AA8', '#A8452F', '#3B6EA8', '#8A6D1F'], COLORES_PERSONA_NUEVO = ['#6D5BF0', '#13795A', '#B83F6E', '#A35A0C', '#1D6A9E', '#9A3BB0']; // 22/10: más oscuros para que la inicial en blanco se lea (contraste ≥ 5)
