  const chip = (k, txt, extra, on) => '<button type="button" class="chip' + (on ? ' active' : '') + '" aria-pressed="' + !!on + '" ' + act('tfCon', k, desde || '') + '>' + (extra || '') + escapeHtml(txt) + '</button>';
