const DINERO_SUBS = [['cuentas', 'Cuentas'], ['metas', 'Metas'], ['inversiones', 'Inversiones'], ['deudas', 'Deudas'], ['compartido', 'Compartido']];
// «Cuentas» va la primera, solo con 2 o más cuentas
