  const yo = miUid(), mapa = {};
  deudasDe(gid).forEach((d) => { if (d.de !== yo && d.a !== yo) return; const otro = d.de === yo ? d.a : d.de, x = mapa[otro] || (mapa[otro] = { uid: otro, nombre: nombreDe(gid, otro), neto: 0 }); x.neto = r2(x.neto + (d.de === yo ? -d.importe : d.importe)); });
