  const cuando = (iso) => { const n = daysUntil(iso); return n === 0 ? 'Hoy' : n === 1 ? 'Mañana' : n < 7 ? DIAS_LARGO[dowMon(parseISO(iso))] : fmtDateShort(iso); };
