  for (let j = n - 1; j >= 0; j--) { let mm = m - j, yy = y; while (mm < 1) { mm += 12; yy--; } const k = kpisMes(yy, mm); meses.push({ y: yy, m: mm, ing: k.ingresos, gas: k.gastos + k.facturas }); }
