const INV_RELLENO = /^(inc\.?|corp\.?|corporation|plc|s\.?a\.?|ag|nv|se|fund|fondo|index|indice|índice|stock|core|eur|usd|acc|dist|ucits|etf|class|clase|fi|the|de|of|a|b|c)$/i;
