  const cuando = per[0] === 'max' ? 'desde que empezaste' : 'en ' + (per[0] === '1s' ? '7 días' : per[0] === '1m' ? 'un mes' : per[0] === '3m' ? '3 meses' : per[0] === '6m' ? '6 meses' : 'un año');
