    '<div style="display:flex;gap:8px;margin-top:10px;"><button class="btn sm ghost" ' + act('metaAsignar', r.id) + '>Asignar aportaciones</button><button class="btn sm ghost" ' + act('metaEditar', r.id) + '>Editar meta</button></div>';
