  return '<span class="bco-ficha' + (cls ? ' ' + cls : '') + (b.letras.length >= 3 ? ' largo' : '') + (b.logo && /-app\./.test(b.logo) ? ' icono' : '') + '" style="--bc:' + b.color + '" aria-hidden="true">' + inner + '</span>';
