  const d = obDia(ob.nomina.dia), cobrosYa = (c.cobros || []).filter((x) => x && x.nombre), nominaYa = cobrosYa.length > 0, factYa = (c.facturas || []).filter((x) => x && x.nombre).map((x) => x.nombre);
