    if (b) { c.banco = b.k; if (!c.nombre) c.nombre = b.n; if (nueva && b.tipo === 'broker') c.tipo = 'broker'; } else delete c.banco;
    cs[i] = c; saveConfig({ cuentas: cs }); sentir('tic');
