    const f = await firmaApp();
    const escribiendo = document.activeElement && /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    if (f && f !== _ver.firma && !$('#sheetBackdrop') && !escribiendo) location.reload();
